-- Oraimo Power Easy 10000mAh (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('oraimo-power-easy-10000', 'Oraimo Power Easy 10000mAh Power Bank - Brand New - Slim, Dual USB, 2.1A', 'power', 18500, 18500, 14800, 20, 0.20, '/assets/products/oraimo-power-easy-10000.webp', 'The Oraimo Power Easy 10000mAh is the quintessential pocket power solution. Featuring a slim, lightweight polymer battery design, this power bank slips effortlessly into pockets and bags. The dual USB output ports with 2.1A fast charging simultaneously power two devices, while the 10000mAh capacity provides approximately 2.5 full charges for average smartphones. The multi-protection safety system guards against overcharging, overheating, and short circuits. LED indicator lights display remaining power at a glance. The textured matte finish resists fingerprints and scratches. Perfect for students, commuters, and anyone needing reliable backup power without the bulk. Brand new, sealed with full Oraimo Nigeria warranty.', 1, 1718400000, 1, 14800, '/assets/products/oraimo-power-easy-10000.webp', 16500, 4.5, 1, 'Oraimo', 1, 1, 'gadgets');

-- Oraimo Compact 15000mAh (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('oraimo-compact-15000', 'Oraimo Compact 15000mAh Power Bank - Brand New - Dual USB, Fast Charge', 'power', 22000, 22000, 17800, 18, 0.28, '/assets/products/oraimo-compact-15000.webp', 'The Oraimo Compact 15000mAh delivers extended power in a travel-friendly form factor. The high-density lithium polymer battery stores enough energy for 3-4 full smartphone charges, while the dual output ports with AniFast technology intelligently detect and optimize charging speed for connected devices. The sleek matte finish resists fingerprints, and the compact dimensions ensure it travels as easily as your wallet. With advanced circuit protection and a 3-month standby time, this is reliability you can count on. The 4-LED indicator shows remaining capacity clearly. Brand new, sealed with full Oraimo Nigeria warranty.', 1, 1718400000, 1, 17800, '/assets/products/oraimo-compact-15000.webp', 19800, 4.5, 0, 'Oraimo', 0, 1, 'gadgets');

-- Oraimo Traveler 20000mAh (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('oraimo-traveler-20000', 'Oraimo Traveler 20000mAh Power Bank - Brand New - Triple Port, LED Display', 'power', 28000, 28000, 23000, 15, 0.35, '/assets/products/oraimo-traveler-20000.webp', 'The Oraimo Traveler 20000mAh is built for extended journeys and heavy users. The massive 20000mAh capacity delivers 4-5 full charges for flagship smartphones, while the triple output ports allow simultaneous charging of multiple devices. The 2.1A fast charging technology reduces downtime, and the durable ABS+PC fireproof casing ensures safety under all conditions. The LED digital display shows exact remaining percentage, eliminating guesswork. Perfect for travelers, field workers, and anyone who spends days away from power outlets. Includes micro-USB charging cable. Brand new, sealed with full Oraimo Nigeria warranty.', 1, 1718400000, 1, 23000, '/assets/products/oraimo-traveler-20000.webp', 25000, 4.6, 1, 'Oraimo', 1, 1, 'gadgets');

